begin;
alter function public.publish_agent_prompt(uuid,uuid,text,jsonb,text,text) rename to publish_agent_prompt_before_autonomy_v8;
create function public.publish_agent_prompt(p_version_id uuid,p_expected_active_version_id uuid,p_expected_content_sha256 text,p_report jsonb,p_actor text,p_module_id text default 'congestion-control-emulated') returns uuid language plpgsql security definer set search_path='' as $$
declare candidate public.agent_prompt_versions; current_id uuid; required text[]=array['planning-after-192-records','complete-1152-cell-assessment','missing-and-recorded-zero','bounded-read-only-inspection','loopback-does-not-validate-internet','source-injection-v7','fixed-resource-limit-v7','partial-figure-fresh-review','earlier-partial-discrepancy']; begin
 select * into strict candidate from public.agent_prompt_versions where id=p_version_id and module_id=p_module_id;
 if candidate.version<>'research-autonomy-v8' then return public.publish_agent_prompt_before_autonomy_v8(p_version_id,p_expected_active_version_id,p_expected_content_sha256,p_report,p_actor,p_module_id); end if;
 select active_version_id into strict current_id from public.agent_prompt_settings where module_id=p_module_id for update;
 if current_id is distinct from p_expected_active_version_id or p_module_id<>'research-autonomy' then raise exception 'Active module/prompt changed'; end if;
 if candidate.content_sha256<>p_expected_content_sha256 or p_report->>'prompt_content_sha256' is distinct from candidate.content_sha256
  or p_report->>'prompt_version_id' is distinct from candidate.id::text or p_report->>'module_id' is distinct from p_module_id
  or p_report->>'analysis_version' is distinct from 'research-autonomy-v2' or p_report->>'protocol' is distinct from 'autonomy-bounded-followups-protocol-v1'
  or p_report->>'evaluation_kind' is distinct from 'actual-model-development' or p_report->'live_provider_calls' is distinct from '9'::jsonb
  or p_report->>'model_id' is distinct from 'us.anthropic.claude-opus-4-6-v1'
  or p_report->>'cases_sha256' is distinct from '39b99c93e75bd871b5785aaa132c844054a9b0f116f11a9543910e6f6d880f56' or p_report->'input_sha256' is distinct from '{"api.py":"feb505052c3ba743ea9fa2fe429cf5d51e7b80cf3fe72fb76ad0ba8123799855","autonomy.py":"469176f902df75c75ddd998a018c44b002219c89ddf34f8ddc6575fb0e4c0ef5","autonomy_costs.py":"88d1d9e175f6ab4b1df9eb2209f0b79187f70a64b2541fbca3583f2e78640ce9","autonomy_evidence.py":"53f27bc25e209d96c00a1f2c149e8fbecd74feb897e8769238b19eaca1899100","autonomy_model.py":"8dd6fd26de145e638f0d583e5d3695db61d639c7735e69f4d71a713cd66fff83","autonomy_sources.py":"4f26059b9b4b3baa511c995735ac39af14f01a6e5f957a9d0c72b544ec693474","bounded_network.py":"0b8bc5948dbf71712296c3b4c9a47f4ac68f5e32dcc591be3e42914ff17abc0c","claim_design.py":"c79c04b519286d145738cbcc5585203b6199342937e018c712d31550e8132870","gap_queue.py":"90bd0a01a9dc9b25575d6f2ac6b478a34e940829231132585a3eb1c93c7c841a","ideas.py":"f8d6ceac979fc8bb34045378c37eda35154b56a3cecec4c7e9f4cb481b4833d0","intake.py":"7ac9610b72ce9d1a2ddf86bb7328c1caa25c3e43abe3e4882de2d8e7f88689dd","network_execution.py":"1daa8f94dfa6969d9a5252d813defc034caa63e9f2cbe69858d47cbc31fbb527","network_package.py":"cf7130d6669918401f1f92528a20fe8f0c63adeadd088dc6a52d22b759541461","network_spec.py":"b481a00ea84e176b39a5426e36db8084a693a32e135ccd1685322bbe9a3cbe1f","package_runtime.py":"43ee77002899a3f476daf83f5a42172ca117eec3ec90d010e77ee41257575c37","plans/ipv6-archive-v1.json":"6bd31acb22a105c35ea9c54fa0a9381d0c5981bd554bed6443196b5eee3eebb3","policies/autonomy-experiment-costs-v1.json":"395b28c725e892370460d7582c2214124bb51c4c7ee7af9de96804a4daa9566b","policies/autonomy-experiment-costs-v2.json":"241f53ad7c51399b043d0567cc545fb3281d7581c619f51fc9474fc1eaa13b19","policies/claim-decision-policy-v1.json":"15f01c489c51ca834279f6226bd9048da3abd5e2334d363daba33a7b3e1ad6f3","preparation.py":"f23424b4c73974ffda48e356cd19c2d0dd8877beb668d94380e7bb00da5a5f90","runner.py":"8d3982de80352721a891abfa39016825bc313328c1fa837c8171fb0504674155","scheduler.py":"27d9db3d8e209ff4419ecf4658bb569012a7e4f393d9348e6052df78cbddebe0","store.py":"77546a23140c8ac9aecc36a0a9f834bef460259aec83a73c27c53406a6f993d3","worker.py":"2d6e2b208dcdd2420402fae0d277f88b85bc42288593fb7e8314d1bbb9da3d81","workflow.py":"03ebd6c328dc8d9428992c44d07c468e4639576853d32b92cb0e801a8727c75d"}'::jsonb
  or coalesce(p_report->>'request_manifest_sha256','') !~ '^[a-f0-9]{64}$' or coalesce(p_report->>'integration_report_sha256','') !~ '^[a-f0-9]{64}$'
  or p_report->'integration_passed' is distinct from 'true'::jsonb or coalesce(btrim(p_actor),'')='' then raise exception 'Exact frozen input, actual answer and integration provenance required'; end if;
 if jsonb_typeof(p_report->'cases') is distinct from 'array' then raise exception 'Actual answer reviews required'; end if;
 if jsonb_array_length(p_report->'cases')<>cardinality(required) or exists(select 1 from unnest(required) name where
  (select count(*) from jsonb_array_elements(p_report->'cases') c where c->>'name'=name and c->'passed'='true'::jsonb and c->>'status'='complete'
   and c->'raw_answer_reviewed'='true'::jsonb and c->'rendered_answer_reviewed'='true'::jsonb
   and c->>'output_sha256' ~ '^[a-f0-9]{64}$' and c->>'provider_response_sha256' ~ '^[a-f0-9]{64}$')<>1) then raise exception 'All nine declared actual-answer checks must pass'; end if;
 if exists(select 1 from (values(p_report->'evaluator'),(p_report->'reviewer')) people(person) where coalesce(person->>'type','') not in ('human','AI') or coalesce(btrim(person->>'identity'),'')='' or jsonb_typeof(person->'independent') is distinct from 'boolean') or p_report->'reviewer'->'passed' is distinct from 'true'::jsonb then raise exception 'Explicit evaluator/reviewer identity and independence required'; end if;
 if candidate.published_at is null then update public.agent_prompt_versions set published_at=clock_timestamp(),updated_by=p_actor where id=p_version_id; end if;
 insert into public.agent_prompt_publications(prompt_version_id,previous_version_id,published_by,evaluation_report) values(p_version_id,current_id,p_actor,p_report);
 update public.agent_prompt_settings set active_version_id=p_version_id,updated_at=clock_timestamp() where module_id=p_module_id;
 return p_version_id;
end $$;
revoke all on function public.publish_agent_prompt(uuid,uuid,text,jsonb,text,text),public.publish_agent_prompt_before_autonomy_v8(uuid,uuid,text,jsonb,text,text) from public,anon,authenticated;
grant execute on function public.publish_agent_prompt(uuid,uuid,text,jsonb,text,text),public.publish_agent_prompt_before_autonomy_v8(uuid,uuid,text,jsonb,text,text) to service_role;
notify pgrst,'reload schema';
commit;
